<?php defined('BASEPATH') or exit('No direct script access allowed');
$refundHidden=static function(array $data)use($hidden,$refund_csrf){$hidden($data+['company_asaas_refund_csrf'=>$refund_csrf]);};
$refundLabel=static fn(string $state)=>match($state){'reserved'=>'Reservada; ainda não enviada','sending'=>'Envio iniciado; resultado não confirmado','uncertain'=>'Resultado incerto; consulte sem reenviar','pending_observed'=>'Em processamento no Asaas','partial_observed'=>'Devolução parcial observada','full_observed'=>'Devolução integral observada','cancelled_observed'=>'Cancelamento observado no Asaas','cancelled_local'=>'Intenção local não enviada cancelada',default=>'Revisão necessária'};
?>
<section id="asaas-refunds"><h2>Reembolsos por origem</h2><p>Reembolso remoto exige autorização explícita deste operador nesta conta. Cada intenção enviada tem no máximo um POST, inclusive após timeout. Consulta preserva os valores originais e não representa baixa ou estorno automático do caixa local. Tarifas da cobrança não são devolvidas por este fluxo.</p>
<ul><?php foreach($origins as $refundOrigin){ ?><li><a href="<?= $e($action_url.'?refund_origin='.(int)$refundOrigin['id'].'#asaas-refund-detail'); ?>">Conferir reembolso da fatura #<?= (int)$refundOrigin['invoice_id']; ?> · <?= $e($refundOrigin['account_id'].' / '.$refundOrigin['environment']); ?></a></li><?php } ?></ul>
<?php if($refund_panel){$rs=$refund_panel['source']; ?><article id="asaas-refund-detail"><h3>Origem #<?= (int)$rs['origin_id']; ?> · Fatura #<?= (int)$rs['invoice_id']; ?></h3><p><?= $e($rs['account_id'].' / '.$rs['environment'].' · '.$rs['remote_id']); ?>. Nominal <?= $e($rs['nominal']); ?> <?= $e($rs['currency']); ?>. Forma <?= $e($rs['billing_type']); ?>.</p>
<?php if($can_refund&&$refund_grant!==null){ ?><form method="post" action="<?= $e($action_url.'?refund_origin='.(int)$rs['origin_id']); ?>"><?php $refundHidden(['action'=>'refund_grant','origin_id'=>$rs['origin_id'],'account_row'=>$rs['account_row'],'revision'=>$refund_grant['revision'],'enabled'=>(int)$refund_grant['enabled']===1?'0':'1']); ?><label><input type="checkbox" name="confirm" value="1" required> Confirmo <?= (int)$refund_grant['enabled']===1?'revogar':'habilitar'; ?> o operador #<?= (int)$refund_actor; ?> para reembolsos desta conta e ambiente, além de suas permissões atuais.</label><button type="submit"><?= (int)$refund_grant['enabled']===1?'Revogar autorização de reembolso':'Autorizar reembolso nesta conta'; ?></button></form><?php }elseif($can_refund){ ?><p>Conta ou autorização indisponível para novos envios. O histórico continua abaixo.</p><?php } ?>
<?php $blockingIntent=(bool)array_filter($refund_panel['requests'],static fn($r)=>$r['sent_at']!==null||$r['state']!=='cancelled_local');if($can_refund&&(int)($refund_grant['enabled']??0)===1&&!$blockingIntent&&in_array($rs['billing_type'],['PIX','CREDIT_CARD'],true)){ ?><form method="post" action="<?= $e($action_url.'?refund_origin='.(int)$rs['origin_id']); ?>"><?php $refundHidden(['action'=>'refund_prepare','origin_id'=>$rs['origin_id'],'request_key'=>$refund_request_key]); ?><label>Valor explícito a devolver (integral ou parcial)<input name="refund_amount" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required></label><label>Motivo<input name="reason" minlength="3" maxlength="160" required></label><label><input type="checkbox" name="confirm" value="1" required> Confirmei valor, conta, ambiente e origem. Esta etapa somente reserva a intenção.</label><button type="submit">Preparar reembolso por origem</button></form><?php } ?>
<?php foreach($refund_panel['requests'] as $intent){ ?><section class="asaas-refund-intent" data-request="<?= $e($intent['request_key']); ?>"><h4><?= $e($refundLabel($intent['state'])); ?></h4><p>Pedido <?= $e($intent['amount']); ?> BRL · operador #<?= (int)$intent['actor_id']; ?> · <?= $e($intent['created_at']); ?> · motivo <?= $e($intent['reason']); ?>.</p>
<?php if($intent['sent_at']!==null){ ?><p>Envio iniciado em <?= $e($intent['sent_at']); ?>. Esta operação não será reenviada, mesmo com resultado incerto. Não crie outra intenção para contornar este estado.</p><?php } ?>
<?php if($intent['observation']!==null){$ob=$intent['observation']; ?><p>Observação <?= $e($intent['observed_at']); ?> por <?= $intent['observed_operation']==='query'?'consulta GET':'resposta ao POST'; ?> · cobrança <?= $e($ob['status']); ?>. Soma concluída <?= $e($ob['done_total']); ?>; pendente <?= $e($ob['pending_total']); ?>; cancelada <?= $e($ob['cancelled_total']); ?> BRL.</p><table><thead><tr><th>Criação no Asaas</th><th>Estado</th><th>Valor</th><th>Comprovante</th></tr></thead><tbody><?php foreach($ob['refunds'] as $item){ ?><tr><td><?= $e($item['date_created']); ?></td><td><?= $e($item['status']); ?></td><td><?= $e($item['value']); ?> BRL</td><td><?php if($item['receipt_url']){ ?><a href="<?= $e($item['receipt_url']); ?>" target="_blank" rel="noopener noreferrer">Comprovante informado pelo Asaas</a><?php } ?></td></tr><?php } ?></tbody></table><?php } ?>
<p role="status">Reflexo financeiro local: não aplicado. <?php if($intent['financial_block']==='partial_refund_identity_contract_required'){ ?>O contrato disponível não garante um identificador único por estorno parcial. E2E, posição do array ou diferença de valores não substituem essa identidade.<?php }else{ ?>O resultado integral observado ainda depende da integração financeira canônica confirmada.<?php } ?></p>
<?php if($can_refund&&$intent['state']==='reserved'&&$intent['sent_at']===null&&(int)$intent['actor_id']===(int)$refund_actor){foreach(['refund_dispatch'=>'Enviar uma única vez a intenção reservada','refund_cancel'=>'Cancelar somente a intenção não enviada'] as $action=>$caption){ ?><form method="post" action="<?= $e($action_url.'?refund_origin='.(int)$rs['origin_id']); ?>"><?php $refundHidden(['action'=>$action,'origin_id'=>$rs['origin_id'],'request_key'=>$intent['request_key']]); ?><label><input type="checkbox" name="confirm" value="1" required> Confirmei esta ação na conta e ambiente desta origem.</label><button type="submit"><?= $e($caption); ?></button></form><?php }}elseif($can_refund&&$intent['sent_at']!==null){ ?><form method="post" action="<?= $e($action_url.'?refund_origin='.(int)$rs['origin_id']); ?>"><?php $refundHidden(['action'=>'refund_refresh','origin_id'=>$rs['origin_id'],'request_key'=>$intent['request_key']]); ?><label><input type="checkbox" name="confirm" value="1" required> Confirmo somente consultar o estado na conta de origem, sem novo POST de reembolso.</label><button type="submit">Consultar reembolso sem reenviar</button></form><?php } ?></section><?php } ?></article><?php } ?></section>
